Correct:
 function setPoint(
  t: SegTree, i: number, v: number, node = 1, l = 0, r = t.n - 1,
): void {
  if (l === r) { t.tree[node] = v; return; }
  const mid = (l + r) >> 1;
  if (i <= mid) setPoint(t, i, v, 2 * node, l, mid);
  else setPoint(t, i, v, 2 * node + 1, mid + 1, r);
  t.tree[node] = (t.tree[2 * node] as number) + (t.tree[2 * node + 1] as number);
