Every insertion must set both directions: next on the old node and prev on the new one
ts-doublylinkedlist-core   lens: creation   level: L0   family: ts-dll-creation
Prerequisites: none. Follow-up: ts-doublylinkedlist-pop-edge. Complexity: O(1).
 Common misconception. Setting only the next links is enough, because prev can be derived when needed.
A doubly linked list stores prev and next on each node so it can be walked in both directions and a node can be
removed in O(1). If pushBack forgets to set prev, forward traversal still works but backward traversal sees nothing. A
tail pointer makes appending O(1); an empty list must set head and tail together.
Incorrect (runs, but fails as described):
 type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
class DllBad<T> {
  head: DNode<T> | null = null;
  tail: DNode<T> | null = null;
  pushBack(value: T): void {
    const node: DNode<T> = { value, prev: null, next: null };
    if (this.tail) this.tail.next = node;
    else this.head = node;
    this.tail = node;
  }
  toArrayReversed(): T[] {
    const out: T[] = [];
    for (let n = this.tail; n; n = n.prev) out.push(n.value);
    return out;
  }
}
Correct:
 type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
class DoublyLinkedList<T> {
  head: DNode<T> | null = null;
  tail: DNode<T> | null = null;
  size = 0;
  pushBack(value: T): DNode<T> {
    const node: DNode<T> = { value, prev: this.tail, next: null };
    if (this.tail) this.tail.next = node;
    else this.head = node;
    this.tail = node;
    this.size++;
    return node;
  }
  pushFront(value: T): DNode<T> {
    const node: DNode<T> = { value, prev: null, next: this.head };
    if (this.head) this.head.prev = node;
    else this.tail = node;
    this.head = node;
    this.size++;
    return node;
  }
  toArray(): T[] {
    const out: T[] = [];
    for (let n = this.head; n; n = n.next) out.push(n.value);
    return out;
  }
  toArrayReversed(): T[] {
    const out: T[] = [];
    for (let n = this.tail; n; n = n.prev) out.push(n.value);
    return out;
  }
}

