Popping the last node must clear head and tail; dereferencing a null prev crashes
ts-doublylinkedlist-pop-edge   lens: edge-cases   level: L1   family: ts-dll-delete
Prerequisites: ts-doublylinkedlist-core. Follow-up: ts-doublylinkedlist-remove-node. Complexity: O(1).
 Common misconception. popBack can always set tail = tail.prev and tail.next = null.
When the list has one node, tail.prev is null, so tail.next = null throws TypeError. The empty-list and single-node
cases must set both head and tail to null and reset the size.
Incorrect (runs, but fails as described):
 type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
type DLike<T> = { head: DNode<T> | null; tail: DNode<T> | null; size: number };
function popBackBad<T>(l: DLike<T>): T | undefined {
  const last = l.tail;
  if (!last) return undefined;
  l.tail = last.prev;
  l.tail!.next = null;
  l.size--;
  return last.value;
}
Correct:
 type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
type DLike<T> = { head: DNode<T> | null; tail: DNode<T> | null; size: number };
function popBack<T>(l: DLike<T>): T | undefined {
  const last = l.tail;
  if (!last) return undefined;
  l.tail = last.prev;
  if (l.tail) l.tail.next = null;
  else l.head = null;
  l.size--;
  return last.value;
}
